() => {
  const rows = document.querySelectorAll('tbody tr');
  const result = [];
  for (const row of rows) {
    const cells = row.querySelectorAll('td');
    if (cells.length >= 2) {
      result.push({
        team: cells[0].textContent.trim(),
        transaction: cells[1].textContent.trim()
      });
    }
  }
  return result;
}

() => {
  const tables = document.querySelectorAll('table');
  const results = [];
  tables.forEach(table => {
    const rows = table.querySelectorAll('tbody tr');
    rows.forEach(row => {
      const cells = row.querySelectorAll('td');
      const team = cells[0] ? cells[0].innerText.trim() : '';
      const transaction = cells[1] ? cells[1].innerText.trim() : '';
      if (team && transaction) {
        results.push(team + ' | ' + transaction);
      }
    });
  });
  return results;
}

