const tables = document.querySelectorAll('table');
let results = [];
for (const table of tables) {
  const dateHeader = table.closest('div')?.querySelector('.Table__Title');
  const date = dateHeader ? dateHeader.textContent.trim() : '';
  const rows = table.querySelectorAll('tbody tr');
  for (const row of rows) {
    const teamCell = row.querySelector('td');
    const transCell = row.querySelectorAll('td')[1];
    const teamLink = teamCell ? teamCell.querySelector('a') : null;
    const team = teamLink ? teamLink.textContent.trim() : (teamCell ? teamCell.textContent.trim() : '');
    const transaction = transCell ? transCell.textContent.trim() : '';
    results.push({date: date, team: team, transaction: transaction});
  }
}
return JSON.stringify(results);
